(232605, 13982, 6892, '<td valign="top">An excellent example of how this challenge has honed our skills of observation.<br/>Well done.</td>', 'An excellent example of how this challenge has honed our skills of observation.Well done.', '2003-03-10 02:58:24.000000', NULL, 1),
(232608, 13807, 6892, '<td valign="top">How versatile a vine can be for curved shapes. The narrow depth of field<br/>does well to separate the number from the background.</td>', 'How versatile a vine can be for curved shapes. The narrow depth of fielddoes well to separate the number from the background.', '2003-03-10 03:02:32.000000', NULL, 1),
(232609, 13702, 6892, '<td valign="top">The use of shadow against the whiteness of snow to create a number was<br/>a great idea.</td>', 'The use of shadow against the whiteness of snow to create a number wasa great idea.', '2003-03-10 03:05:29.000000', NULL, 1),
(232611, 13760, 6892, '<td valign="top">The effect here was so subtle as to almost be missed, but it works.</td>', 'The effect here was so subtle as to almost be missed, but it works.', '2003-03-10 03:08:49.000000', NULL, 1),
(232614, 13979, 6892, '<td valign="top">I think so many of us were so involved searching for numerical shapes that we missed the very simple aspect of counting...this is a lovely gardeners stock photo.</td>', 'I think so many of us were so involved searching for numerical shapes that we missed the very simple aspect of counting...this is a lovely gardeners stock photo.', '2003-03-10 03:12:33.000000', NULL, 1),
