(232617, 13967, 6892, '<td valign="top">You were fortunate to find this interesting sandstone formation. Good detail.</td>', 'You were fortunate to find this interesting sandstone formation. Good detail.', '2003-03-10 03:19:35.000000', NULL, 1),
