(233277, 13702, 1280, '<td valign="top">Very clearly a four...good job!</td>', 'Very clearly a four...good job!', '2003-03-10 12:51:02.000000', NULL, 1),
(233282, 13759, 1280, '<td valign="top">Yes...I see it.  Good job!</td>', 'Yes...I see it.  Good job!', '2003-03-10 12:55:22.000000', NULL, 1),
