(233310, 13610, 1280, '<td valign="top">Very good indeed!</td>', 'Very good indeed!', '2003-03-10 13:05:49.000000', NULL, 1),
(233318, 13877, 6100, '<td valign="top">I like that you don'' t have any hot spots in this photo. Personally, I would try to light the right side just a little bit and see what that looked like. Looks like a big "1" to me!</td>', 'I like that you don'' t have any hot spots in this photo. Personally, I would try to light the right side just a little bit and see what that looked like. Looks like a big "1" to me!', '2003-03-10 13:09:27.000000', NULL, 1),
(233320, 13742, 6100, '<td valign="top">The tilted background is distracting but I see the "7" you were going for.</td>', 'The tilted background is distracting but I see the "7" you were going for.', '2003-03-10 13:10:09.000000', NULL, 1),
(233337, 13656, 2279, '<td valign="top">Wow that looks REALLY REALLY cold.</td>', 'Wow that looks REALLY REALLY cold.', '2003-03-10 13:14:45.000000', NULL, 1),
(233342, 13898, 3599, '<td valign="top">I''m not sure I like all of the negative space.  Maybe a tighter crop?  I think you met the challenge well though.  Good work and good luck.</td>', 'I''m not sure I like all of the negative space.  Maybe a tighter crop?  I think you met the challenge well though.  Good work and good luck.', '2003-03-10 13:16:00.000000', NULL, 1),
(233344, 13902, 6100, '<td valign="top">Your concept is quite clever.</td>', 'Your concept is quite clever.', '2003-03-10 13:16:46.000000', NULL, 1),
(233350, 13656, 5212, '<td valign="top">Great shot, nice use of the challenge, good work for b.w.  I might have lightened this up just a tad, but that''s just me craving some bright spots in the photo.</td>', 'Great shot, nice use of the challenge, good work for b.w.  I might have lightened this up just a tad, but that''s just me craving some bright spots in the photo.', '2003-03-10 13:21:20.000000', NULL, 1),
