(233708, 13834, 6855, '<td valign="top">Nice shot!  I think it would have looked better in color, but your cropping is very nice!</td>', 'Nice shot!  I think it would have looked better in color, but your cropping is very nice!', '2003-03-10 15:39:45.000000', NULL, 1),
(233709, 13696, 6855, '<td valign="top">Beautiful - I absolutely LOVE the lighting and the color. Very pretty.</td>', 'Beautiful - I absolutely LOVE the lighting and the color. Very pretty.', '2003-03-10 15:40:50.000000', NULL, 1),
(233711, 13689, 6855, '<td valign="top">I love the tonal finish on this, and the lighting is great.</td>', 'I love the tonal finish on this, and the lighting is great.', '2003-03-10 15:41:27.000000', NULL, 1),
