(233737, 13626, 6504, '<td valign="top">I think too many members have used the shell, but this is a good photograph.<br/>The color and texture is very good.</td>', 'I think too many members have used the shell, but this is a good photograph.The color and texture is very good.', '2003-03-10 15:49:55.000000', NULL, 1),
(233740, 13631, 6504, '<td valign="top">Ooops.  Where''s the naturally ocurring number?  Is on there that I don''t see?<br/>I would like to see this photo a little sharper.</td>', 'Ooops.  Where''s the naturally ocurring number?  Is on there that I don''t see?I would like to see this photo a little sharper.', '2003-03-10 15:50:47.000000', NULL, 1),
(233742, 13883, 6504, '<td valign="top">I don''t see a number, do you?   It is just a little too dark for me.</td>', 'I don''t see a number, do you?   It is just a little too dark for me.', '2003-03-10 15:51:26.000000', NULL, 1),
