(233844, 13815, 4494, '<td valign="top">Excellent!  Love the DOF on this with the very blurry background.  Good job.</td>', 'Excellent!  Love the DOF on this with the very blurry background.  Good job.', '2003-03-10 16:50:17.000000', NULL, 1),
(233848, 13569, 4494, '<td valign="top">This one will win probably.  It is EXCELLENT!!  I love the red background also.  The only thing is without the reflection of the shell might have been a little better. 9.</td>', 'This one will win probably.  It is EXCELLENT!!  I love the red background also.  The only thing is without the reflection of the shell might have been a little better. 9.', '2003-03-10 16:54:24.000000', NULL, 1),
