(233853, 13682, 4494, '<td valign="top">The top of the leaf is a little blurry.  Try using a high apprature to reduc the DOF maybe.</td>', 'The top of the leaf is a little blurry.  Try using a high apprature to reduc the DOF maybe.', '2003-03-10 16:56:57.000000', NULL, 1),
