(235043, 13915, 6504, '<td valign="top">Very nice wide angle picture.  I like the lighting at the top.  I see the one by one...</td>', 'Very nice wide angle picture.  I like the lighting at the top.  I see the one by one...', '2003-03-11 13:34:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(235044, 13967, 6504, '<td valign="top">The colors are good, texture could be brought out a little more.  Defininely a zero, which was the challenge.t</td>', 'The colors are good, texture could be brought out a little more.  Defininely a zero, which was the challenge.t', '2003-03-11 13:35:53.000000', NULL, 1),
(235045, 13722, 6504, '<td valign="top">This picture could be just a tiny bit more sharp, but you did capture the number 7!.</td>', 'This picture could be just a tiny bit more sharp, but you did capture the number 7!.', '2003-03-11 13:36:26.000000', NULL, 1),
(235046, 13774, 6504, '<td valign="top">Very good four!  The snow on the bottom part of the four accents the number.<br/></td>', 'Very good four!  The snow on the bottom part of the four accents the number.', '2003-03-11 13:37:06.000000', NULL, 1),
(235047, 13720, 6504, '<td valign="top">Yup, that is an 8!   Notice the sign is more sharp than the vegetable, a little sharper focus and this could be great!</td>', 'Yup, that is an 8!   Notice the sign is more sharp than the vegetable, a little sharper focus and this could be great!', '2003-03-11 13:38:17.000000', NULL, 1),
(235048, 13732, 6504, '<td valign="top">It''s as if this tree were just waiting for you and dpchallenge.</td>', 'It''s as if this tree were just waiting for you and dpchallenge.', '2003-03-11 13:39:03.000000', NULL, 1),
(235049, 13834, 6504, '<td valign="top">I think it is very clever that you saw the number two in these geese''s necks.<br/>Very well done.</td>', 'I think it is very clever that you saw the number two in these geese''s necks.Very well done.', '2003-03-11 13:40:19.000000', NULL, 1),
(235050, 13819, 6504, '<td valign="top">I don''t see the number.  I would have waited another minute for the person to move out of the picture.  What is all the rubble below?  I can''t quite make it out. Is that a flag in the middle of the rubble?</td>', 'I don''t see the number.  I would have waited another minute for the person to move out of the picture.  What is all the rubble below?  I can''t quite make it out. Is that a flag in the middle of the rubble?', '2003-03-11 13:41:44.000000', NULL, 1),
(235344, 13624, 1280, '<td valign="top">Definetly a four in there! Freaky sculpture!  I think we had some of this series in Albany, NY for a summer or two.<br/>Good job!</td>', 'Definetly a four in there! Freaky sculpture!  I think we had some of this series in Albany, NY for a summer or two.Good job!', '2003-03-11 19:20:35.000000', NULL, 1),
(235348, 13815, 1280, '<td valign="top">Yes...it''s a three, and pretty too. I love foliage pictures.  Well seen, and well done. If I''d change anything, it would probably be to have less negative space. I still like it.</td>', 'Yes...it''s a three, and pretty too. I love foliage pictures.  Well seen, and well done. If I''d change anything, it would probably be to have less negative space. I still like it.', '2003-03-11 19:23:46.000000', NULL, 1),
(235357, 13656, 1280, '<td valign="top">I love this one!  It meets the challenge nicley with the all those sevens, and you did a good job of exposing.  A little, just a little lighter, I think, would improve it.  I think it''s excellent though. One of my favorites this week!</td>', 'I love this one!  It meets the challenge nicley with the all those sevens, and you did a good job of exposing.  A little, just a little lighter, I think, would improve it.  I think it''s excellent though. One of my favorites this week!', '2003-03-11 19:27:57.000000', NULL, 1),
(235366, 13661, 1280, '<td valign="top">Nice, simple, uncomplicated. I like the softness of the bg, and the boldness of the trees.  Good contrast.</td>', 'Nice, simple, uncomplicated. I like the softness of the bg, and the boldness of the trees.  Good contrast.', '2003-03-11 19:31:48.000000', NULL, 1),
(235368, 13626, 1280, '<td valign="top">Very good nine!!! Well done.</td>', 'Very good nine!!! Well done.', '2003-03-11 19:32:36.000000', NULL, 1),
(235370, 13902, 1280, '<td valign="top">You found a three!  Colorful one too!</td>', 'You found a three!  Colorful one too!', '2003-03-11 19:34:37.000000', NULL, 1),
(235376, 13620, 1280, '<td valign="top">I see a five, I see a two. Well seen!</td>', 'I see a five, I see a two. Well seen!', '2003-03-11 19:37:05.000000', NULL, 1),
(235384, 13682, 1280, '<td valign="top">Lovely indeed, and clearly there. General focus is a little soft.  Perhaps you meant for that to be.  I''d prefer crisper, sharper focus.<br/>Nevertheless good job!</td>', 'Lovely indeed, and clearly there. General focus is a little soft.  Perhaps you meant for that to be.  I''d prefer crisper, sharper focus.Nevertheless good job!', '2003-03-11 19:43:32.000000', NULL, 1),
(235389, 13829, 1280, '<td valign="top">A good eight!</td>', 'A good eight!', '2003-03-11 19:48:29.000000', NULL, 1),
(235393, 13672, 1280, '<td valign="top">Very pretty abstract.  I don''t know what it is but I see an eleven.  It doesn''t matter to me that I can''t identify this.  Actually I like this kind of abstract.  I do look forward to you revealing the identity. <br/>Great colors. There is a bit of grain, and I suppose you''ll take some heat for that.  Doesn''t bother me any.<br/>Nice pic!  Good luck!</td>', 'Very pretty abstract.  I don''t know what it is but I see an eleven.  It doesn''t matter to me that I can''t identify this.  Actually I like this kind of abstract.  I do look forward to you revealing the identity. Great colors. There is a bit of grain, and I suppose you''ll take some heat for that.  Doesn''t bother me any.Nice pic!  Good luck!', '2003-03-11 19:51:47.000000', NULL, 1),
