INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(237874, 13682, 3585, '<td valign="top">This is an good number. I think it would have been exploited better if you had framed down to it.</td>', 'This is an good number. I think it would have been exploited better if you had framed down to it.', '2003-03-16 05:25:35.000000', NULL, 1),
(237878, 13736, 1863, '<td valign="top">very nice crisp photo, it''s almost obvious that it''s a 7 :) I like the colours, great attempt. annida</td>', 'very nice crisp photo, it''s almost obvious that it''s a 7 :) I like the colours, great attempt. annida', '2003-03-16 08:10:21.000000', NULL, 1),
(237879, 13790, 1863, '<td valign="top">Very nice 7  you have there. I like this picture. What is a bit odd is the background which seems to blend with the branch. It''s a shame you didn''t play with the contrasts more to bring out the branch more. Well done though -annida</td>', 'Very nice 7  you have there. I like this picture. What is a bit odd is the background which seems to blend with the branch. It''s a shame you didn''t play with the contrasts more to bring out the branch more. Well done though -annida', '2003-03-16 08:11:11.000000', NULL, 1),
(237880, 13759, 1863, '<td valign="top">It''s hard to see the four, because of the background and all the other upward moving branch things. But, it''s there, and it''s tres cool. I like your desaturation of the colours in this. they work well. -annida</td>', 'It''s hard to see the four, because of the background and all the other upward moving branch things. But, it''s there, and it''s tres cool. I like your desaturation of the colours in this. they work well. -annida', '2003-03-16 08:12:17.000000', NULL, 1),
(237881, 13883, 1863, '<td valign="top">That''s the TINIEST little 8 I''ve ever seen. lol. Very clever. I''m impressed you even noticed it. Well done. Annida</td>', 'That''s the TINIEST little 8 I''ve ever seen. lol. Very clever. I''m impressed you even noticed it. Well done. Annida', '2003-03-16 08:12:56.000000', NULL, 1),
(237882, 13982, 1863, '<td valign="top">So many 7''s, laughs, this is one of the pricklier ones :) I like your DOF, and the detail on this uh, plant is very successfully caught. well done. high marks. annida</td>', 'So many 7''s, laughs, this is one of the pricklier ones :) I like your DOF, and the detail on this uh, plant is very successfully caught. well done. high marks. annida', '2003-03-16 08:13:57.000000', NULL, 1),
(237883, 13717, 1863, '<td valign="top">Nice use of dof. a bit over exposed on the top part of the 8. Although I like this, it''s not exactly what I believed was required from the challenge description. My apologies if you''ve heard this a million times before.</td>', 'Nice use of dof. a bit over exposed on the top part of the 8. Although I like this, it''s not exactly what I believed was required from the challenge description. My apologies if you''ve heard this a million times before.', '2003-03-16 08:15:16.000000', NULL, 1),
(237884, 13682, 1863, '<td valign="top">Yes, it is! I love this photo. I''m not usually a fan of flower shots, but damn, this is stunningly part of the challenge, and just strange enough to catch my attention. I like how the 6 is the most in focus bit. well done.</td>', 'Yes, it is! I love this photo. I''m not usually a fan of flower shots, but damn, this is stunningly part of the challenge, and just strange enough to catch my attention. I like how the 6 is the most in focus bit. well done.', '2003-03-16 08:16:39.000000', NULL, 1),
(237885, 13885, 1863, '<td valign="top">mmm, I wouldn''t mind a bite out of that! The colours are delicious, perfect for a photo of food. man, I''m drooling. high marks on this one. well done.</td>', 'mmm, I wouldn''t mind a bite out of that! The colours are delicious, perfect for a photo of food. man, I''m drooling. high marks on this one. well done.', '2003-03-16 08:18:00.000000', NULL, 1),
